INSERT INTO lr_questions (section_id, qid, preptest, section, question_number, question_type, stimulus, prompt, correct_choice, is_explained, source_note) SELECT s.id, $batch04$PT138-S4-Q5$batch04$, 138, 4, 5, $batch04$Paradox$batch04$, $batch04$Recent epidemiological studies report that Country X has the lowest incidence of disease P of any country. Nevertheless, residents of Country X who are reported to have contracted disease P are much more likely to die from it than are residents of any other country.$batch04$, $batch04$Which one of the following, if true, most helps to resolve the apparent discrepancy described above?$batch04$, $batch04$C$batch04$, true, $batch04$Batch 04; question text from local bank.$batch04$ FROM lr_sections s WHERE s.preptest=138 AND s.section=4 AND NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch04$PT138-S4-Q5$batch04$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch04$A$batch04$, $batch04$There are several forms of disease P, some of which are more contagious than others.$batch04$, $batch04$No Impact$batch04$, false FROM lr_questions q WHERE q.qid=$batch04$PT138-S4-Q5$batch04$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch04$A$batch04$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch04$B$batch04$, $batch04$Most of the fatal cases of disease P found in Country X involve people who do not reside in Country X.$batch04$, $batch04$Out of Scope$batch04$, false FROM lr_questions q WHERE q.qid=$batch04$PT138-S4-Q5$batch04$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch04$B$batch04$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch04$C$batch04$, $batch04$In Country X, diagnosis of disease P seldom occurs except in the most severe cases of the disease.$batch04$, $batch04$Correct$batch04$, true FROM lr_questions q WHERE q.qid=$batch04$PT138-S4-Q5$batch04$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch04$C$batch04$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch04$D$batch04$, $batch04$The number of cases of disease P that occur in any country fluctuates widely from year to year.$batch04$, $batch04$No Impact$batch04$, false FROM lr_questions q WHERE q.qid=$batch04$PT138-S4-Q5$batch04$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch04$D$batch04$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch04$E$batch04$, $batch04$Because of its climate, more potentially fatal illnesses occur in Country X than in many other countries.$batch04$, $batch04$Out of Scope$batch04$, false FROM lr_questions q WHERE q.qid=$batch04$PT138-S4-Q5$batch04$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch04$E$batch04$) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch04$PT138-S4-Q5$batch04$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch04$Given that$batch04$, $batch04$Country X has the lowest reported rate of disease P of any country.$batch04$), (1, $batch04$How can it be that$batch04$, $batch04$Residents of Country X reported to have it are much more likely to die from it than residents of any other country?$batch04$), (2, $batch04$Evaluate$batch04$, $batch04$Both numbers depend on which cases get *reported*. If Country X only diagnoses the worst cases, it would record few cases, and the ones it records would be the deadliest.$batch04$), (3, $batch04$Goal$batch04$, $batch04$Find a reason Country X records fewer and more severe cases.$batch04$)) v(position,label,body) WHERE q.qid=$batch04$PT138-S4-Q5$batch04$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch04$A$batch04$, $batch04$Some forms being more contagious does not explain the gap between low incidence and high deaths.$batch04$), ($batch04$B$batch04$, $batch04$The stimulus is about *residents* of Country X. Deaths among nonresidents do not explain it.$batch04$), ($batch04$C$batch04$, $batch04$Country X seldom diagnoses the disease except in the most severe cases. Mild cases go uncounted, which keeps the reported rate low. The cases that are counted are the deadly ones, which drives up the death rate.$batch04$), ($batch04$D$batch04$, $batch04$Year-to-year swings in the number of cases affect every country and do not explain this gap.$batch04$), ($batch04$E$batch04$, $batch04$More potentially fatal illnesses in general says nothing about disease P.$batch04$)) v(letter,body) WHERE q.qid=$batch04$PT138-S4-Q5$batch04$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
